code.C:
#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int c0 = 0, c1 = 0;
    for (int i = 0; i < n; i++) {
        int x; scanf("%d", &x);
        if (x == 0) c0++; else if (x == 1) c1++;
    }
    printf("0:%d\n1:%d\n", c0, c1);
    return 0;
}

