import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            int c0 = 0, c1 = 0;
            for (int i = 0; i < n; i++) {
                int x = sc.nextInt();
                if (x == 0) c0++; else if (x == 1) c1++;
            }
            System.out.println("0:" + c0 + "\n1:" + c1);
        }
    }
}

