    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    let c0 = 0, c1 = 0;
    for (let i = 1; i <= n; i++) {
        if (toks[i] === "0") c0++;
        else if (toks[i] === "1") c1++;
    }
    console.log(`0:${c0}\n1:${c1}`);
}
main();

